CREATE TABLE IF NOT EXISTS automations (id VARCHAR(36) PRIMARY KEY, team_id VARCHAR(36) NOT NULL, owner_id VARCHAR(36) NOT NULL, `name` VARCHAR(120) NOT NULL, trigger_kind VARCHAR(16) NOT NULL, cron VARCHAR(200) NULL, timezone VARCHAR(64) NULL, catchup VARCHAR(8) NOT NULL, catchup_grace_minutes INT NOT NULL, action_kind VARCHAR(16) NOT NULL, profile_id VARCHAR(36) NULL, model VARCHAR(128) NULL, effort VARCHAR(32) NULL, max_runtime_minutes INT NOT NULL, prompt MEDIUMTEXT NOT NULL, variables text NOT NULL, sample_payload MEDIUMTEXT NULL, overlap VARCHAR(8) NOT NULL, max_runs_per_day INT NOT NULL, enabled BOOLEAN NOT NULL, disabled_reason VARCHAR(64) NULL, disabled_by VARCHAR(36) NULL, version INT NOT NULL, next_run_at BIGINT NULL, consecutive_failures INT NOT NULL, secret text NULL, previous_secret text NULL, previous_secret_until BIGINT NULL, secret_rotated_at BIGINT NOT NULL, credential_id VARCHAR(36) NULL, last_run_id VARCHAR(36) NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, CONSTRAINT automations_owner FOREIGN KEY (owner_id) REFERENCES members(id), CONSTRAINT automations_credential FOREIGN KEY (credential_id) REFERENCES tokens(id) ON DELETE SET NULL);
CREATE INDEX automation_owner ON automations (team_id, owner_id, created_at);
CREATE INDEX automation_team ON automations (team_id, created_at);
CREATE INDEX automation_due ON automations (enabled, trigger_kind, next_run_at);